// STUB — Phase 8 Skeleton
// PURPOSE: Load Brand Brain data for Vị Cuốn
// PRODUCTION: Read from brand-brain/vi-cuon.md via filesystem, Google Sheets, or Supabase
// CREDENTIAL NEEDED: REPLACE_WITH_GOOGLE_SHEETS_CREDENTIAL or REPLACE_WITH_SUPABASE_CREDENTIAL

const inputData = $input.first().json;

const brandBrain = {
  brand_name: inputData.brand_name || 'Vị Cuốn',
  brand_positioning: 'REPLACE_WITH_BRAND_POSITIONING',
  target_customer: 'REPLACE_WITH_TARGET_CUSTOMER',
  menu_items: 'REPLACE_WITH_MENU_ITEMS',
  price_range: 'REPLACE_WITH_PRICE_RANGE',
  address: 'REPLACE_WITH_ADDRESS',
  opening_hours: 'REPLACE_WITH_OPENING_HOURS',
  key_offers: 'REPLACE_WITH_KEY_OFFERS',
  tone_of_voice: 'REPLACE_WITH_TONE_OF_VOICE',
  forbidden_claims: 'REPLACE_WITH_FORBIDDEN_CLAIMS',
  approval_status: 'REPLACE_WITH_APPROVAL_STATUS'
};

return [{ json: { ...inputData, brandBrain, brandBrainLoaded: true } }];

// STUB — Phase 8 Skeleton
// PURPOSE: Call AI model to generate CRM follow-up message sequence
// PRODUCTION: HTTP Request to Claude API (claude-sonnet-4-6) or equivalent LLM
// CREDENTIAL NEEDED: REPLACE_WITH_ANTHROPIC_API_KEY
// CONSTRAINT: No real API call in skeleton. Returns mock CRM sequence object.
// SCHEMA: Output must conform to schemas/crm-followup.schema.json
// CRITICAL: human_review_required is ALWAYS true (schema const: true)
// CRITICAL: No customer PII in message templates at draft stage

const inputData = $input.first().json;

// Mock CRM sequence — all required fields from crm-followup.schema.json
const crmSequence = {
  sequence_id: 'CRM-VQ-STUB-001',
  brand_id: inputData.brand_id || 'VQ',
  brand_name: inputData.brand_name || 'Vị Cuốn',
  lead_segment: inputData.lead_segment || 'New Customer',
  customer_status: inputData.customer_status || 'New Lead',
  channel: inputData.channel || 'Facebook Messenger',
  trigger_event: inputData.trigger_event || 'REPLACE_WITH_TRIGGER_EVENT',
  message_sequence: [
    {
      step: 1,
      delay: 'Immediately',
      message_template: 'STUB_MSG_1 — Replace with AI-generated welcome message. Use [CUSTOMER_NAME] as personalization placeholder.'
    },
    {
      step: 2,
      delay: '1 day',
      message_template: 'STUB_MSG_2 — Replace with AI-generated follow-up. Include offer: [OWNER_TO_PROVIDE_OFFER].'
    },
    {
      step: 3,
      delay: '3 days',
      message_template: 'STUB_MSG_3 — Replace with AI-generated final follow-up. Include opt-out option.'
    }
  ],
  recommended_timing: 'Weekdays 11am-1pm and 5pm-7pm (Vinh, Vietnam time)',
  human_review_required: true,
  approval_status: 'Draft',
  created_by_agent: 'n8n-crm-followup-auto (STUB)',
  created_at: new Date().toISOString(),
  notes: 'Phase 8 skeleton stub. No real AI call. No messages sent to real customers. human_review_required=true always.'
};

return [{ json: { ...inputData, crmSequence, aiCallCompleted: true } }];

// STUB — Phase 8 Skeleton
// PURPOSE: Validate CRM sequence against crm-followup.schema.json required fields
// SCHEMA REF: schemas/crm-followup.schema.json
// REQUIRED: sequence_id, brand_id, brand_name, lead_segment, customer_status,
//   channel, trigger_event, message_sequence (array min 1),
//   human_review_required (must be true), approval_status, created_by_agent, created_at

const inputData = $input.first().json;
const seq = inputData.crmSequence || {};

const requiredFields = [
  'sequence_id', 'brand_id', 'brand_name', 'lead_segment',
  'customer_status', 'channel', 'trigger_event',
  'approval_status', 'created_by_agent', 'created_at'
];

const missingFields = requiredFields.filter(f => !seq[f] || seq[f] === '');

// message_sequence must be array with at least 1 item
if (!Array.isArray(seq.message_sequence) || seq.message_sequence.length === 0) {
  missingFields.push('message_sequence (must be array with at least 1 item)');
}

// human_review_required must be true (schema const)
if (seq.human_review_required !== true) {
  missingFields.push('human_review_required (must be true — schema const)');
}

const validationPass = missingFields.length === 0;
const validationErrors = missingFields.map(f => `SCHEMA_VALIDATION_FAIL: ${f}`);

return [{ json: { ...inputData, validation_pass: validationPass, validation_errors: validationErrors } }];

// STUB — Phase 8 Skeleton
// PURPOSE: Write structured log entry per schemas/log-entry.schema.json
// PRODUCTION: Append to Google Sheets log tab or Supabase logs table
// CREDENTIAL NEEDED: REPLACE_WITH_GOOGLE_SHEETS_CREDENTIAL or REPLACE_WITH_SUPABASE_CREDENTIAL

const inputData = $input.first().json;
const seq = inputData.crmSequence || {};

const logEntry = {
  log_id: 'LOG-' + new Date().toISOString().slice(0, 10).replace(/-/g, '') + '-STUB-001',
  timestamp: new Date().toISOString(),
  phase: '8',
  agent_name: 'n8n-crm-followup-auto (STUB)',
  action_type: 'CRM Sequence Draft',
  input_ref: inputData.trigger_event || 'STUB_INPUT',
  output_ref: seq.sequence_id || 'STUB_OUTPUT',
  status: 'Success',
  summary: 'CRM Follow-Up Auto skeleton executed. Draft created. human_review_required=true. No messages sent.',
  errors: (inputData.validation_errors && inputData.validation_errors.length) ? inputData.validation_errors : null,
  next_action: 'Send sequence to approval queue. Owner to review all message templates before any send.',
  owner_action_required: false
};

return [{ json: { ...inputData, logEntry, logWritten: true } }];
